"""Retrying a call that may fail transiently."""

TRANSIENT = (OSError,)


def retry(call, attempts):
    """The value of ``call()``, calling it at most ``attempts`` times.

    A transient error on the last attempt is raised.
    """
    for attempt in range(attempts + 1):
        try:
            return call()
        except TRANSIENT:
            if attempt == attempts:
                raise

