"""URL slugs."""

import re

_NON_WORD = re.compile(r"[^a-z0-9]+")


def slug(title):
    """``title`` lower-cased, each run of other characters one hyphen, none at either end."""
    return _NON_WORD.sub("-", title.lower()).strip("-")

